mapper.select:
select s.*, c.name as clazz_name, col.name as college_name
from student s
left join clazz c on s.clazz_id = c.id
left join college col on s.college_id = col.id


        and s.name like concat('%', #{name}, '%')


        and s.clazz_id = #{clazzId}


        and s.college_id = #{collegeId}


        and s.degree = #{degree}


        and s.create_time between #{begin} and #{end}


order by s.create_time desc

mapper.update:
update student
name = #{name}, no = #{no}, gender = #{gender}, phone = #{phone}, clazz_id = #{clazzId}, college_id = #{collegeId}, degree = #{degree}, admission_date = #{admissionDate}, image = #{image}, update_time = #{updateTime},
where id = #{id}
